/**
 *
 * ProgressSpinner is a process status indicator.
 *
 * [Live Demo](https://www.primevue.dev/progressspinner)
 *
 * @module progressspinnerstyle
 *
 */
import type { BaseStyle, BaseStyleModule } from '@primevue/core/base/style';

export enum ProgressSpinnerClasses {
    /**
     * Class name of the root element
     */
    root = 'p-progressspinner',
    /**
     * Class name of the circle element
     */
    circle = 'p-progressspinner-circle',
    /**
     * Class name of the circle track element
     */
    circleTrack = 'p-progressspinner-circle-track',
    /**
     * Class name of the circle range element
     */
    circleRange = 'p-progressspinner-circle-range',
    /**
     * Class name of the value element
     */
    value = 'p-progressspinner-value'
}

export interface ProgressSpinnerStyle extends BaseStyle {}

declare const ProgressSpinnerStyle: BaseStyleModule;

export default ProgressSpinnerStyle;
